import React from 'react';
import { Calculator, BarChart3, Target, TrendingUp, BookOpen, Activity } from 'lucide-react';

/**
 * Home Tab - Overview and quick access to probability tools
 */
export default function HomeTab() {
  const quickAccessTools = [
    {
      id: 'basic-probability',
      title: 'Basic Probability',
      description: 'Calculate probabilities for simple and compound events',
      icon: Calculator,
      color: 'blue'
    },
    {
      id: 'distributions',
      title: 'Distributions',
      description: 'Explore normal, binomial, and other statistical distributions',
      icon: BarChart3,
      color: 'green'
    },
    {
      id: 'hypothesis-testing',
      title: 'Hypothesis Testing',
      description: 'Perform t-tests, chi-square tests, and ANOVA',
      icon: Target,
      color: 'purple'
    },
    {
      id: 'regression-analysis',
      title: 'Regression Analysis',
      description: 'Linear and multiple regression modeling',
      icon: TrendingUp,
      color: 'orange'
    }
  ];

  const getColorClasses = (color) => {
    const colorMap = {
      blue: 'bg-blue-100 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 border-blue-200 dark:border-blue-800',
      green: 'bg-green-100 dark:bg-green-900/20 text-green-600 dark:text-green-400 border-green-200 dark:border-green-800',
      purple: 'bg-purple-100 dark:bg-purple-900/20 text-purple-600 dark:text-purple-400 border-purple-200 dark:border-purple-800',
      orange: 'bg-orange-100 dark:bg-orange-900/20 text-orange-600 dark:text-orange-400 border-orange-200 dark:border-orange-800'
    };
    return colorMap[color] || colorMap.blue;
  };

  return (
    <div className="px-4 sm:px-6 lg:px-8 py-8">
      {/* Header Section */}
      <div className="text-center mb-12">
        <div className="flex justify-center mb-6">
          <div className="p-4 bg-gradient-to-br from-red-500 to-red-600 rounded-2xl shadow-lg">
            <Activity className="h-12 w-12 text-white" />
          </div>
        </div>
        <h1 className="text-4xl font-bold text-gray-900 dark:text-white mb-4">
          Probability Suite
        </h1>
        <p className="text-xl text-gray-600 dark:text-gray-300 max-w-3xl mx-auto">
          Comprehensive statistical analysis tools for probability calculations,
          distribution analysis, hypothesis testing, and regression modeling.
        </p>
      </div>

      {/* Quick Access Grid */}
      <div className="mb-12">
        <h2 className="text-2xl font-semibold text-gray-900 dark:text-white mb-6 flex items-center">
          <BookOpen className="h-6 w-6 mr-3 text-red-500" />
          Quick Access Tools
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {quickAccessTools.map((tool) => {
            const Icon = tool.icon;
            return (
              <div
                key={tool.id}
                className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6 hover:shadow-md transition-shadow duration-200"
              >
                <div className="flex items-start space-x-4">
                  <div className={`p-3 rounded-lg ${getColorClasses(tool.color)}`}>
                    <Icon className="h-6 w-6" />
                  </div>
                  <div className="flex-1">
                    <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">
                      {tool.title}
                    </h3>
                    <p className="text-gray-600 dark:text-gray-300 text-sm">
                      {tool.description}
                    </p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Features Overview */}
      <div className="bg-gradient-to-br from-red-50 to-orange-50 dark:from-red-900/10 dark:to-orange-900/10 rounded-2xl p-8 border border-red-100 dark:border-red-800/30">
        <h2 className="text-2xl font-semibold text-gray-900 dark:text-white mb-6">
          Suite Features
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="text-center">
            <div className="inline-flex items-center justify-center w-12 h-12 bg-red-100 dark:bg-red-900/30 rounded-lg mb-4">
              <Calculator className="h-6 w-6 text-red-600 dark:text-red-400" />
            </div>
            <h3 className="font-semibold text-gray-900 dark:text-white mb-2">
              Interactive Calculators
            </h3>
            <p className="text-sm text-gray-600 dark:text-gray-300">
              Real-time probability and statistical calculations with visual feedback
            </p>
          </div>
          <div className="text-center">
            <div className="inline-flex items-center justify-center w-12 h-12 bg-red-100 dark:bg-red-900/30 rounded-lg mb-4">
              <BarChart3 className="h-6 w-6 text-red-600 dark:text-red-400" />
            </div>
            <h3 className="font-semibold text-gray-900 dark:text-white mb-2">
              Statistical Visualizations
            </h3>
            <p className="text-sm text-gray-600 dark:text-gray-300">
              Charts and graphs to visualize distributions and test results
            </p>
          </div>
          <div className="text-center">
            <div className="inline-flex items-center justify-center w-12 h-12 bg-red-100 dark:bg-red-900/30 rounded-lg mb-4">
              <BookOpen className="h-6 w-6 text-red-600 dark:text-red-400" />
            </div>
            <h3 className="font-semibold text-gray-900 dark:text-white mb-2">
              Educational Content
            </h3>
            <p className="text-sm text-gray-600 dark:text-gray-300">
              Explanations and examples for each statistical concept and test
            </p>
          </div>
        </div>
      </div>

      {/* Getting Started */}
      <div className="mt-12 text-center">
        <h2 className="text-2xl font-semibold text-gray-900 dark:text-white mb-4">
          Getting Started
        </h2>
        <p className="text-gray-600 dark:text-gray-300 mb-6 max-w-2xl mx-auto">
          Select a tool from the navigation menu or use the quick access cards above to begin your statistical analysis.
          Each tool includes step-by-step guidance and educational content.
        </p>
        <div className="flex justify-center">
          <div className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700 shadow-sm">
            <p className="text-sm text-gray-500 dark:text-gray-400">
              💡 <strong>Tip:</strong> Use keyboard navigation (Arrow keys) to quickly switch between tools
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
